options.afterRender:
(function(){
  try {
    var el = context.element, df = context.dataFrame;
    if (!df || !df.fields || !df.length) { el.innerHTML='<div style="color:#888;padding:12px;font-family:Inter,sans-serif">Sin datos en el rango</div>'; return; }
    var get=function(n){var f=df.fields.find(function(f){return f.name===n});if(!f)return[];var v=f.values;return (v&&v.toArray)?v.toArray():v;};
    var pos=get('pos'), ath=get('athlete_id'), t=get('t'), dif=get('dif'), tu=get('tu');
    var fmtT=function(s){s=Math.round(s);var h=Math.floor(s/3600),m=Math.floor((s%3600)/60),ss=s%60;var mm=(h>0&&m<10?'0':'')+m;return (h>0?h+':':'')+mm+':'+(ss<10?'0':'')+ss;};
    var fmtD=function(s){s=Math.round(s); if(s<=0) return 'Lider'; var m=Math.floor(s/60),ss=s%60; return '+'+m+':'+(ss<10?'0':'')+ss;};
    var medal=function(p){return p===1?'':p===2?'':p===3?'':String(p);};
    var n=pos.length, rows='';
    for(var i=0;i<n;i++){
      var sel = Number(tu[i])===1;
      var tdb = 'padding:8px 10px;border-bottom:1px solid rgba(255,255,255,0.05);';
      var tr = sel ? 'background:rgba(245,224,3,0.16);' : (i%2 ? 'background:rgba(255,255,255,0.018);' : '');
      var nm = sel ? 'color:#f5e003;font-weight:700;' : 'color:#e8e9ed;';
      var df1 = sel ? 'color:#f5e003;' : 'color:#9aa0a6;';
      var lead = sel ? 'border-left:3px solid #f5e003;' : 'border-left:3px solid transparent;';
      rows += '<tr onclick="location.href=\'/d/hyrox-analysis?var-athlete_id='+ath[i]+'\'" style="cursor:pointer;'+tr+'">'
        + '<td style="'+tdb+lead+'text-align:center;width:58px;font-size:15px;">'+medal(Number(pos[i]))+'</td>'
        + '<td style="'+tdb+nm+'">'+ath[i]+'</td>'
        + '<td style="'+tdb+'text-align:right;color:#ffffff;font-variant-numeric:tabular-nums;">'+fmtT(Number(t[i]))+'</td>'
        + '<td style="'+tdb+df1+'text-align:right;font-variant-numeric:tabular-nums;">'+fmtD(Number(dif[i]))+'</td>'
        + '</tr>';
    }
    var th='padding:8px 10px;border-bottom:2px solid #2a2c31;color:#8e9099;font-size:11px;text-transform:uppercase;letter-spacing:.05em;';
    el.innerHTML =
      '<div style="font-family:Inter,system-ui,sans-serif;height:100%;overflow:auto;">'
      + '<table style="width:100%;border-collapse:collapse;font-size:14px;">'
      + '<thead><tr>'
      + '<th style="'+th+'text-align:center;">#</th>'
      + '<th style="'+th+'text-align:left;">Atleta</th>'
      + '<th style="'+th+'text-align:right;">Tiempo</th>'
      + '<th style="'+th+'text-align:right;">Dif.</th>'
      + '</tr></thead><tbody>'+rows+'</tbody></table></div>';
  } catch(e){ context.element.innerHTML='<div style="color:#c0392b;padding:10px;font-family:monospace">err: '+e.message+'</div>'; }
})();
